window.PORTFOLIO_STORIES = [{"id": "avaron", "aspiration": "Make work outside formal practice visible and turn it into understandable training decisions. The source-supported technical exploration spans mobile interface design, anatomical visualization, deterministic training logic, authenticated backend contracts and infrastructure. These are documented product/engineering aims, not an invented first-person account of what Joey felt he learned.", "usage": ["An athlete records or builds a session, or follows work assigned by a coach.", "Training history and a readiness check-in feed the body view; the interface summarizes body zones and allows anatomy details to be explored.", "The user can inspect a recommended exercise, start a session, advance through timed or logged work and finish it.", "Coach/team surfaces provide another view of the work. This walkthrough describes repository behavior and existing demo media; it was not exercised against a live account."], "technology": [{"title": "Flutter and Dart", "text": "The mobile tree contains body-map data/domain/providers/views and anatomical rendering components, alongside sessions, workouts and team features."}, {"title": "Math and explanation have different jobs", "text": "The project vision explicitly assigns readiness, fatigue, progression and training decisions to deterministic rules/math; AI serves content and language interfaces. This is an architectural intent, not an independent validation of scientific accuracy."}, {"title": "Backend with explicit contracts", "text": "NestJS/TypeScript domains include sessions, coach, exercises, tissue health, wearables and moderation. Auth/RLS-preserving access and route dispatch boundaries are documented; source names retaining Supabase do not mean hosted Supabase is the active operational backend."}, {"title": "Operating the platform", "text": "CloudNativePG/PostgreSQL on k3s, PostgREST, gateways, observability and release/runner tooling live in the same organization repository. Current canonical architecture notes override stale migration-era wording in apps/api/README.md."}, {"title": "Fresh deterministic module demonstration", "text": "The actual pure Dart sportFitnessScore module ran locally on synthetic inputs. Empty/unknown evidence returned null, a measured zero returned 0, and scores 60 weighted twice plus 80 weighted once returned 66.6667. Adding an unknown all-zero row did not lower that result. This tests evidence-handling semantics, not training science or the full app."}], "learning": [{"title": "Make a complex model legible", "text": "Source-supported learning topic: anatomical drawing, body-zone navigation, cached repositories and readable training-status copy connect a deep internal model to a small set of user decisions."}, {"title": "Reliability is part of the interface", "text": "Reviewed demo feedback points to save/completion, back navigation and imported-activity problems. The useful story is how feedback identifies engineering work; the minutes alone do not prove every follow-up shipped."}, {"title": "Build and operate across layers", "text": "Joey-authored history supports work beyond screens, including candidate lease recovery and execution budgets. Describe concrete changes without crediting one person for the entire team platform."}], "screenshots": [{"src": "assets/stories/media/avaron/app-tour-frame-55.png", "caption": "Anatomy detail from the existing README app tour.", "kind": "existing app-tour frame", "date": "2026-08-13"}, {"src": "assets/stories/media/avaron/app-tour-frame-80.png", "caption": "Readiness check-in from the existing README tour; visually checked generic body/check-in screen.", "kind": "existing app-tour frame", "date": "2026-08-13"}, {"src": "assets/stories/media/avaron/app-tour-frame-106.png", "caption": "Workout timer from the existing README tour; generic exercise screen, visually checked.", "kind": "existing app-tour frame", "date": "2026-08-13"}, {"src": "assets/stories/media/avaron/offline-module-output.png", "caption": "Fresh local stdout from the actual Dart sportFitnessScore helper with synthetic inputs, rendered for readability.", "kind": "fresh offline module execution output render", "date": "2026-10-30"}]}, {"id": "sensor", "aspiration": "Explore the complete path from physical motion to recoverable data: schematic and layout, battery/power protection, firmware acquisition, persistent storage and export. The current R2 is an engineering recorder for future AVARON integration, not proof of a finished athlete wearable.", "usage": ["Engineering workflow: inspect the KiCad project and review the power, MCU/sensors and battery sheets before considering fabrication. The current order hold must remain visible.", "After the outstanding hardware checks and assembly, intended bring-up uses the documented debugger/power wiring and compiled firmware. No such board operation was performed here.", "Firmware documentation describes recording motion into external flash, explicit start/stop/status controls, and stopped-session export through USB or encrypted BLE.", "Host tools decode records and surface sequence/gap information. Explicit format/provisioning commands are separate engineering operations; they were not executed."], "technology": [{"title": "KiCad design and review", "text": "The project has a four-layer rectangular development board, hierarchical schematic sheets, custom symbols/footprints and review PDFs. Power-path, ESD, connector and pin-map issues are documented with corrections and remaining constraints."}, {"title": "C and Zephyr", "text": "Firmware separates IMU acquisition, fuel-gauge handling, flash storage/service, recording policy and telemetry. It targets an nRF52840 module and ICM-42688-P six-axis IMU."}, {"title": "Persistence and transport", "text": "Source/documentation describe a journal in external NOR flash plus BLE and USB export. Explicit statuses, recovery and data-gap checks matter as much as receiving samples."}, {"title": "Software verification", "text": "A focused host protocol suite checks signed raw axes, wire byte order, invalid frame sizes and bounded capture duration. Three tests passed during this research session; this does not validate hardware acquisition or radio behavior."}], "learning": [{"title": "Schematic correctness versus a working board", "text": "Source-supported learning topic: ERC/DRC and generated artifacts are useful gates but cannot substitute for powered validation, battery qualification or RF testing."}, {"title": "Power design is a system", "text": "Review findings connect charger, fuel gauge, protection, thermistor and USB host behavior. This supports a concrete electronics story about interfaces and failure paths rather than a claim of production readiness."}, {"title": "Design for data recovery", "text": "Recorder source and tests make queue ownership, byte order, timestamps, interrupted records and explicit erase behavior inspectable. These are documented technical topics, not an invented personal retrospective."}], "screenshots": [{"src": "assets/stories/media/sensor/layout.png", "caption": "Actual PCB-layout review PDF rendered locally and framed to its vector drawing.", "kind": "actual PDF artifact render", "date": "2026-09-09"}, {"src": "assets/stories/media/sensor/schematic.png", "caption": "Power-management page of the actual schematic review PDF, rendered locally.", "kind": "actual PDF artifact render", "date": "2026-09-09"}]}, {"id": "hirebolt", "aspiration": "Hirebolt brings job discovery and application preparation into one local workspace. The aspiration was more than filling text boxes: bring postings from employer boards into a ranked feed, keep application state understandable, and make locally generated answers and resumes inspectable before anything is submitted. For this portfolio, the learning thread is the connection between a Python service, a React interface, a browser extension and local language models. Building across those boundaries makes the small details—field meaning, uploaded-file identity and interrupted workflows—part of the engineering problem.", "usage": ["Set up a local profile, a master resume and the backend. Choose which public employer boards to watch or capture a posting from the extension.", "Browse the ranked feed, inspect the match explanation and move an interesting role into the application workspace. The demonstration uses invented companies and a fictional applicant.", "Prepare role-specific material and use the extension to fill a form. Review inferred, missing and drafted values. The committed interface also exposes a user-started auto-apply batch workflow with target counts and blocked-application states; this supersedes the README’s older manual-only description. No batch or submission was started here.", "Track the application afterward. The recent workflow preserves submission details and the uploaded resume when it can be verified, so later preparation does not silently replace that history."], "technology": [{"title": "Three surfaces, one contract", "text": "FastAPI and SQLite hold the local state; React/Vite presents jobs and a tracker; the extension operates inside third-party application forms. The API definitions make them parts of one system instead of three disconnected utilities."}, {"title": "Grounded field planning", "text": "field_contracts.py represents meaning, value shape and choice binding explicitly. The planner is not supposed to invent applicant answers. Workers resolve a typed request from available evidence."}, {"title": "Independent review", "text": "answer_validation.py assesses a live readback against candidate evidence. Separating filling from reviewing is a concrete way to reason about a form that looks completed but contains the wrong thing."}, {"title": "Local AI as a subsystem", "text": "Ollama-backed drafting, semantic matching and resume preparation sit around ordinary deterministic workflows. For the local capture those model calls and all board/mail syncing were disabled; the feed and tracker still ran."}], "learning": [{"title": "Browser automation is a state problem", "text": "Useful learning topics include embedded forms, multiple widget types, file attachments, asynchronous preparation and recovery after interruption. A selector clicking successfully is only one part of getting an application into the intended state."}, {"title": "Explainability belongs in the interface", "text": "Match reasons, field-review states and verified submission artifacts turn automation into something a person can inspect. That is a stronger technical story than a claim about applying to many jobs."}], "screenshots": [{"src": "assets/stories/media/hirebolt/feed.png", "caption": "Actual Hirebolt feed, running locally with fictional jobs and a fictional profile.", "kind": "local app / synthetic data", "date": "2026-10-30"}, {"src": "assets/stories/media/hirebolt/tracker.png", "caption": "Actual tracker interface with synthetic saved, applied and interviewing states.", "kind": "local app / synthetic data", "date": "2026-10-30"}]}, {"id": "cockfights", "aspiration": "A third-person bird fighting game is a place to explore several techniques that only become interesting together: movement feel, readable combat, camera behavior, network state, character presentation and interfaces that stay out of the fight. The current repository contains a Unity project and a substantial record of iteration. The user confirms learning tools and techniques as a project motive. A reviewed October 30 design note adds more specific intent: reduce menu noise, give each screen a clear primary action and move the HUD away from the bird rather than cover the action.", "usage": ["The repository describes a Unity game with a starter bird roster, arenas, practice/training and local story progression, plus online modes.", "Local play uses movement/aim controls and peck/kick actions; the game's own move bar explains additional controls.", "The review serves the existing local WebGL build read-only in a fresh browser context, blocking every non-loopback HTTP request and all WebSockets.", "No public account, multiplayer service, ranked result or remote leaderboard is exercised; any capture is an offline local-build observation."], "technology": [{"title": "Movement as explicit state", "text": "BirdMotor has a command-driven path for NPCs and scripted drivers, with separate movement, facing and traversal state. BirdMotor.Network captures/restores position, velocity and movement timers so state can be handled beyond a single local input loop."}, {"title": "Presentation that respects play", "text": "The October 30 reviewed UI spec keeps the middle of the fight clear, groups match information at the top, and gives each menu one dominant action. The game remains on Unity UI Toolkit with C#-built trees and USS; this is source-backed design/engineering work, not only a visual mood board."}, {"title": "An art and qualification pipeline", "text": "The repository includes Blender-related export tooling, character animation previews, menu/HUD capture evidence and build tooling."}], "learning": [{"title": "Coordinating systems without hiding their limits", "text": "Game feel crosses motor code, animation, combat feedback and camera behavior. The code and iteration history make those useful technical topics. The offline WebGL run is a visual reproduction attempt, not proof of network authority or every gameplay mode."}, {"title": "Turning feedback into concrete constraints", "text": "The approved redesign note translates owner feedback into testable layout constraints: a clear centre, one primary action and readable menus at qualified sizes. That is a stronger learning story than simply saying the interface was redesigned."}], "screenshots": [{"src": "assets/stories/media/cockfights/local-menu.png", "caption": "Actual existing Unity WebGL build served read-only on loopback in a fresh browser context.", "kind": "actual local game interface", "date": "2026-10-30"}, {"src": "assets/stories/media/cockfights/local-training.png", "caption": "Actual local Unity WebGL Training screen reached from the main menu.", "kind": "actual local game interface", "date": "2026-10-30"}]}, {"id": "reelforge", "aspiration": "The original design separates two questions: how to describe a reusable short-video format, and how to adapt it into an original brief for a particular product. ReelForge is the product-agnostic Python/CLI core; AVARON reels is the production adapter around it. The aspiration was a repeatable creative toolchain with structured evidence, pacing and costs, not a button that copies somebody else’s video. It is a good learning project for turning fuzzy creative direction into typed data and predictable tooling.", "usage": ["Describe a product through a profile and provide manual references or configured trend sources. The isolated run used one synthetic manual input and no external sources.", "Analyze a reference into a format card, then plan a mix of modes such as culture or a brief end plug. The format and evidence are kept separate from a specific final clip.", "Generate or supply a beat sheet, inspect its hook, timing, shots, dialogue and disclosures, then run lint before exporting. The captured export uses an existing repository test fixture, not a newly generated script.", "In AVARON reels, assign media and voices to beats, inspect missing/short assets, stage a validated package and render or hand-finish it. The local dashboard capture deliberately shows an unfilled fixture brief."], "technology": [{"title": "Typed storytelling", "text": "BeatSheet, Beat, Shot, Cut and source-reference models make duration, continuity, shot kind and disclosures explicit. Validators reject malformed timing rather than leaving every problem to a video editor."}, {"title": "Lint for creative constraints", "text": "Pacing and cut rhythm are treated as checkable constraints. Rules can flag held pictures, slow hooks or unsupported claims while leaving room for the creative script itself."}, {"title": "A separate production adapter", "text": "avaron_reels.stage checks voice and media coverage before writing files. This addresses a practical failure mode: missing or short media can shift later cues even when a renderer produces an output file."}, {"title": "Budget-aware integration", "text": "Provider clients, cached cards, replay fixtures and spending caps isolate expensive model calls. The captured scout/export run made no paid inference requests; that is a reproduction condition, not a monthly-spend achievement."}], "learning": [{"title": "Model the handoff", "text": "A central learning topic is deciding what the next tool needs: a stable JSON beat sheet, meaningful timing and explicit missing assets. A renderer cannot recover an intention that was never represented."}, {"title": "Creative automation still needs checks", "text": "Separating evidence, script, media assignment and export makes failures inspectable. The production dashboard is useful because it exposes the work remaining rather than treating a written brief as a finished video."}], "screenshots": [{"src": "assets/stories/media/reelforge/execution.png", "caption": "Actual CLI output shown in a labeled evidence viewer.", "kind": "actual execution / evidence viewer", "date": "2026-10-30"}, {"src": "assets/stories/media/reelforge/dashboard.png", "caption": "Actual AVARON reels dashboard with a test-fixture brief and deliberately unassigned production assets.", "kind": "local app / fixture brief", "date": "2026-10-30"}]}, {"id": "videos", "aspiration": "This toolkit explores animation as programming: characters, pencil texture, movement, scene composition, sound and an exportable timeline live in code. The aspiration is a reusable collection of short AVARON stories rather than a different hand-edited project for every clip. My contribution sits within a repository owned by Dcorl, so the story focuses on the player, voice/audio integration and specific changes supported by my commits.", "usage": ["Open a video’s portrait or landscape HTML page in a browser. Shared scripts provide the drawing kit, cast and motion; the video script supplies its scene timeline.", "Play, pause or scrub to a precise time. A URL fragment can open a specific frame, which makes review and reproduction much easier than an approximate recording.", "Review sound and spoken lines against the picture. The player handles the shared audio clock and the code describes mixing and mastering behavior.", "Save a frame or use the browser export path when its encoding/muxing requirements are available. The present run captured a frame only; it did not publish or export a finished ad."], "technology": [{"title": "Canvas as an animation system", "text": "The shared pencil drawing kit and character movement routines turn JavaScript into a small production environment. Per-video scripts can reuse a cast while staging different jokes or training moments."}, {"title": "An audio-led timeline", "text": "The player renders sound into a buffer, then uses that clock for playback and seeking. This is a concrete synchronization problem: frame position, captions and speech should agree when the viewer scrubs."}, {"title": "Browser media tooling", "text": "The export source uses VideoEncoder, AudioEncoder and an MP4 muxer. Frame stepping avoids relying on real-time playback speed to capture every frame; the muxer is an external dependency, not authored codec technology."}, {"title": "Two frame shapes", "text": "Portrait and landscape variants share the underlying scene language but recompose content. That is a useful design constraint: responsive storytelling is not simply shrinking the same image."}], "learning": [{"title": "Reusable visual primitives", "text": "A shared character/pose/drawing vocabulary lets a codebase behave like a small animation library. The interesting learning topic is how to keep a playful visual style while making it programmable."}, {"title": "Sync and export boundaries", "text": "Playback, audio gain, encoded peaks and export are related but different systems. Recent commits around voice delivery and the master ceiling show how much of the work sits after drawing the characters."}], "screenshots": [{"src": "assets/stories/media/videos/frame.png", "caption": "Actual landscape Practice Ends canvas frame at t=12.4s, rendered locally.", "kind": "local canvas rendering", "date": "2026-10-30"}]}, {"id": "checkers", "aspiration": "A learning project about turning a familiar board game into an environment for experimenting with decisions. Instead of starting with a black-box learning library, the repository builds the board, legal moves, captures, rewards, policies and trajectory records in Python. The user confirms that learning new tools and techniques was the common motivation across these projects. Here the source supports game simulation, search, reinforcement-learning experiments and numerical data handling as the relevant learning areas. It does not establish a trained agent's strength or convergence.", "usage": ["Create a fresh Board and choose policies for the white and black players through PolicyEnum.", "Ask the board for legal actions and advance turns through play; compare random, lookahead and rollout approaches where implemented.", "Inspect terminal board output and recorded state transitions; use trajectory files as inputs to the LSTD exploration.", "Treat the separate policy_gradient.py as unfinished working material rather than a runnable entry point."], "technology": [{"title": "Rules before learning", "text": "The Board class represents the board as a NumPy array and implements move generation, secondary captures, rewards and endgame handling. That gives the learning experiments an explicit environment rather than hiding the game's mechanics."}, {"title": "Trajectory logging as a data structure problem", "text": "Joey's commits implement a linked-list board history and write state, move and reward information to TSV. Capturing the right transitions is an engineering step of its own: a learner cannot recover information the simulator never recorded."}, {"title": "Multiple decision strategies", "text": "PolicyEnum and main.py expose random, lookahead, rollouts, LSTD and policy-gradient paths. The separate training scripts and incomplete scratch file show experimentation at different levels of completeness, not one uniformly finished algorithm suite."}], "learning": [{"title": "Knowing what a demonstration proves", "text": "A simulator producing legal-looking states is different from an RL policy learning well. The incomplete standalone policy-gradient file stays part of the story because it records the boundary between an idea, an experiment and an implementation."}], "screenshots": [{"src": "assets/stories/media/checkers/evidence.png", "caption": "Actual Board simulator output after ten plies, alongside a source excerpt.", "kind": "local source execution / synthetic fresh game", "date": "2026-10-30"}]}, {"id": "cryptornal", "aspiration": "An encrypted journal was the named direction; the surviving work is an early experiment with the cryptographic building blocks. As a learning project, it connects an everyday application idea to a concrete question: how do you derive an encryption key from a password, encrypt a message and recover it? The source answers that small round-trip question. It does not answer the much larger questions involved in a usable private journal, such as durable storage, reopening entries, password changes, salt persistence, recovery or a user interface.", "usage": ["Run the standalone Python script with the cryptography dependency available.", "The sample derives a key from a hardcoded demonstration password and a fresh random salt.", "It encrypts a hardcoded sample message, decrypts the resulting token and prints whether the recovered bytes match.", "Use it as a cryptographic proof of concept; there is no journal UI or saved-entry workflow in this version."], "technology": [{"title": "Password-derived keys", "text": "PBKDF2HMAC uses SHA-256 and a random 16-byte salt to derive 32 bytes. The source configures 100,000 iterations; that is a historical implementation fact, not a current security recommendation."}, {"title": "Authenticated encryption interface", "text": "The derived bytes are URL-safe base64 encoded for Fernet. The encryption/decryption calls make the round trip visible without implementing a cipher by hand. The cryptography library supplies the cryptographic primitive."}, {"title": "A small executable boundary", "text": "The complete project source is one short main.py. The new local run executes that file unchanged against its original sample input and captures the encrypted token and the True equality result."}], "learning": [{"title": "Understanding the pieces behind an application idea", "text": "The code supports learning about the relationship between passwords, salts, key derivation, encodings and encrypted tokens. The visible result is a successful round trip; it is not a claim that the application has a complete security design."}, {"title": "Recognizing the gap from prototype to product", "text": "A fresh random salt created on every run is useful inside this one process. A persistent journal would need a designed way to retain the information needed for later decryption. No such storage format is present, which makes the stopping point clear and useful to document."}], "screenshots": [{"src": "assets/stories/media/cryptornal/evidence.png", "caption": "Unchanged original cryptornal script and actual local ciphertext/equality output, presented in an evidence viewer.", "kind": "original script execution", "date": "2026-10-30"}]}, {"id": "discord", "aspiration": "A small, playful way to learn asynchronous Python and connect code to a shared chat environment. The bot has straightforward utility and random-response commands instead of a large application model. That is appropriate to its scale: it turns a command into an event handler, reads arguments, awaits a response and exposes feedback in a familiar place. The user confirms learning tools and techniques as the common project motivation; the code supports async command handling, simple integrations and deployment packaging as the specific themes here.", "usage": ["In its original context, a Discord bot account would join a server and listen for commands using the dot prefix.", "Commands include integer addition, latency reporting, a coin flip, a magic-8-ball style response and other playful messages.", "The demonstration exercises argument handling and response logic, not the original deployment environment."], "technology": [{"title": "Asynchronous handlers", "text": "discord.ext.commands decorates async functions. Each handler awaits ctx.send, which makes event-driven responses explicit and introduces Python coroutine syntax in a small setting."}, {"title": "Small functions with observable results", "text": "The addition command receives typed integer arguments. Coin flips and 8-ball responses use random choices. The latency command reads the client latency and formats milliseconds. These are simple behaviors that are easy to verify independently of a real chat connection."}, {"title": "Deployment as part of the experiment", "text": "The repository contains a requirements file and a Procfile, and commit messages include preparing for a server. Those are evidence of packaging/deployment intent, not proof that the bot is still hosted or active."}], "learning": [{"title": "Separating bot logic from the service", "text": "That illustrates a useful boundary: response behavior can be checked without possessing a live credential or posting to a real community."}, {"title": "Integration maintenance has a lifetime", "text": "The snapshot is from 2020. No current discord.py compatibility or account permissions were tested. Its value in the portfolio is as an early integration exercise, rather than an implied current bot service or a production-grade moderation system."}], "screenshots": [{"src": "assets/stories/media/discord/evidence.png", "caption": "Original async command bodies executed with a fake send context; no Discord client connection.", "kind": "offline command fixture", "date": "2026-10-30"}]}, {"id": "hueprint", "aspiration": "HuePrint explores the gap between a flat professional building plan and a space someone can understand in three dimensions. The original scope imagined a contractor uploading a blueprint, walking a client through the resulting house, swapping paint, siding, roofing and window finishes, and exporting the selections. That larger ambition made it a useful learning project across file processing, computer vision, geometry and browser rendering. The surviving implementation is a partial pipeline toward that goal; it is not evidence of a finished automatic design or material-selection product.", "usage": ["Upload one PDF, PNG or JPEG blueprint. The interface validates the file before rendering or converting it into pixel data.", "Review the preprocessed image and confirm a drawing scale. Automatic scale detection is a placeholder suggestion, so this manual step is essential.", "Run feature detection and inspect the overlay before continuing. Current source offers client-side Hough detection plus optional server-backed vector, text and ML paths.", "Continue into a Three.js model preview and orbit, pan or zoom around the detected geometry. This preview visualizes the detector's output; it does not independently certify a complete or accurate house."], "technology": [{"title": "From pixels to candidate walls", "text": "The current client path preprocesses ImageData with luminance conversion and contrast stretching, then runs a custom Canny pipeline: Gaussian blur, Sobel gradients, nonmaximum suppression and hysteresis edge tracking. A Hough-based wall detector and segment merging turn that edge map into candidate geometry. This is a concrete implementation story about replacing incompatible libraries with a small inspectable algorithm, not a claim of production-grade architectural recognition."}, {"title": "Keeping drawing space and world space separate", "text": "Scale parsing and coordinate-mapping utilities translate pixel measurements into world units. Wall endpoints are clustered with union-find before geometry is assembled. React Three Fiber components then position walls, floors and ceilings, with conditional CSG openings for detected doors and windows. Lazy loading keeps the 3D dependency chain out of the initial upload interface."}, {"title": "A browser pipeline with explicit review points", "text": "The workflow is a state machine spanning upload, PDF page selection, conversion, preprocessing, scale, detection and modeling. Current uncommitted code adds multiple detection modes and fallbacks; the portfolio should distinguish that inspected working tree from the last committed February snapshot. Source also retains older OpenCV worker scaffolding, so the active hook implementation is more reliable evidence than a stale architectural summary."}], "learning": [{"title": "Computer vision has failure modes that a UI must expose", "text": "The interesting learning topic is not simply detecting lines. Real plans contain text, title blocks, double wall edges, broken segments and different scales. The detector overlay and manual scale step make those assumptions visible. In the synthetic capture, only two walls were detected from a plan containing several more. The resulting incomplete model is useful evidence of the project's actual limit, rather than something to hide behind an attractive 3D screenshot."}, {"title": "Geometry needs topology and units, not just boxes", "text": "Endpoint snapping, segment orientation, opening placement and unit conversion all affect whether neighboring walls meet. This project offers a practical way to discuss moving from image-processing output to a stable scene graph. It also illustrates that rendering a model and reconstructing the correct building are different achievements."}, {"title": "Scope can remain ambitious while the artifact stays honest", "text": "First-person walkthroughs, live material customization and a material list belong to the documented aspiration. They should appear as intended next steps, not current capabilities. The strongest personal-site story is the attempt to connect these disciplines and what the intermediate pipeline reveals about that problem."}], "screenshots": [{"src": "assets/stories/media/hueprint/upload.png", "caption": "Actual local HuePrint upload interface, captured from an isolated source snapshot.", "kind": "local application screenshot", "date": "2026-10-30"}, {"src": "assets/stories/media/hueprint/scale.png", "caption": "Actual scale-confirmation interface using a synthetic plan; the automatic scale suggestion is a placeholder.", "kind": "local application screenshot with synthetic input", "date": "2026-10-30"}, {"src": "assets/stories/media/hueprint/detection.png", "caption": "Actual client-side result: only two candidate walls detected from the synthetic multi-room plan.", "kind": "local application screenshot with synthetic input", "date": "2026-10-30"}, {"src": "assets/stories/media/hueprint/model.png", "caption": "Actual 3D stage reached with the same two-wall result.", "kind": "local application screenshot with synthetic input", "date": "2026-10-30"}]}, {"id": "umiviz", "aspiration": "UmiViz asks how much of a physical-product showroom can fit into a small embedded web viewer. The documented target was a wheel-rim configurator: choose an OBJ model, select Chrome, Matte Black, Gunmetal or another finish, then inspect it from any angle without installing software. The learning opportunity was practical browser graphics rather than a large app framework: model loading, physically based materials, lighting, camera controls, asset serving and a simple surrounding interface. Later phases were meant to add a model selector and embed integration; the surviving work is primarily the viewer and server foundation.", "usage": ["Register an OBJ filename in the model manifest and serve it from the project's model directory.", "Open viewer.html with a model query parameter and optionally a finish parameter. The camera computes a fit from the loaded geometry's bounding box.", "Drag to orbit, scroll to zoom and use the right mouse button to pan. Click a finish swatch to update the material in place.", "Use the lower-left Turntable button to start or stop auto-rotation. The local portfolio capture uses a synthetic rim shape, not an owned/customer product asset."], "technology": [{"title": "PBR needs an environment to reflect", "text": "The viewer uses MeshStandardMaterial with separate color, metalness and roughness values for five finishes. A RoomEnvironment is converted through PMREMGenerator and assigned to the scene before the OBJ loads. That setup gives reflective materials something meaningful to reflect. The documented decision is more informative than a generic claim of using Three.js: the project explicitly identified the environment map as necessary for the metallic appearance."}, {"title": "One renderer, multiple product surfaces", "text": "OBJLoader returns a group rather than one mesh, so finish updates traverse child meshes. OrbitControls supplies damping and optional auto-rotation, while setAnimationLoop keeps rendering and control updates synchronized. Box3-based camera fitting avoids assuming whether an uploaded model uses millimeters, centimeters or inches. A transparent canvas lets the CSS gradient remain the visual background."}, {"title": "Serving models is part of the design", "text": "The Express route reads a manifest and checks path containment, the .obj extension and manifest membership before returning a file. The renderer and API are separate development processes. For this capture, an isolated Vite proxy explicitly rewrites the viewer's /models request to the implemented /api/models route; this capture adapter is documented rather than presented as proof the original default integration was complete."}], "learning": [{"title": "Material parameters and light must work together", "text": "This is a useful study in the difference between painting an object gray and making a metal finish readable. Roughness, metalness, environment reflections and a controlled background all affect the result. The synthetic geometry in these screenshots has simple faceted normals, so it tests the original renderer and controls without pretending to be a finished photoreal product model."}, {"title": "A small component still has integration boundaries", "text": "URL parameters, loading states, camera fitting, file allowlists and parent-site embedding make a viewer more than a rotating mesh. Each is a concrete learning topic visible in source. The unfinished selector and embed phases are worth mentioning because they explain the gap between a working viewer and a complete configurator."}, {"title": "Test assets and real product assets have different roles", "text": "A reproducible synthetic OBJ is enough to exercise loading, finish switching and rotation. It does not establish ownership of a particular wheel design or demonstrate customer adoption. Keeping that boundary explicit makes the technical learning story stronger and easier to verify."}], "screenshots": [{"src": "assets/stories/media/umiviz/chrome.png", "caption": "Actual UmiViz renderer in Chrome finish, with explicitly synthetic rim geometry.", "kind": "local application screenshot with synthetic asset", "date": "2026-10-30"}, {"src": "assets/stories/media/umiviz/gunmetal.png", "caption": "Actual Gunmetal finish after changing the swatch and running the turntable.", "kind": "local application screenshot with synthetic asset", "date": "2026-10-30"}]}, {"id": "leads", "aspiration": "LeadsByMail began with address and street-view tooling, then developed toward a pipeline that reconstructs a recognizable house view from geospatial inputs and assembles advertising material. A later aspiration was a door-to-door companion: a representative photographs a house and shows a proposed after image. The learning value lies in connecting coordinate systems, geometry, rendering, image conditioning and print output. The portfolio should distinguish that ambitious pipeline from what an isolated geometry demonstration can prove.", "usage": ["Supply an address or the corresponding geospatial inputs, obtain a footprint and elevation/context information, and convert them into a local scene. This original data-fetch path was not run against real properties.", "Construct the building and surroundings, choose a camera and render a reference view. The local experiment executes the original mesh builders on one invented rectangular footprint.", "Use the rendering and context as inputs to the documented image-generation/validation workflow, then assemble a mailer. No paid image calls or campaign records were used in the capture.", "The planned companion reverses the input emphasis: start with a doorstep photograph and display an after-image comparison. Its roadmap is recorded; this pass does not present it as a shipped Flutter app."], "technology": [{"title": "Geographic to local coordinates", "text": "mesh_builder.py converts latitude/longitude to a local metric frame around a centroid. That makes camera placement, roof geometry and terrain meaningful in metres rather than arbitrary geographic units."}, {"title": "Roof-aware mesh construction", "text": "The original dispatcher selects hip, gable, flat or pyramid builders. The local plot shows hip, gable and flat meshes built from the same synthetic footprint, making the algorithmic differences visible."}, {"title": "A hybrid rendering pipeline", "text": "Source includes ModernGL shaders, Trimesh meshes, terrain/camera utilities and image-conditioning/validation code. They solve different parts of the problem; a plausible generated image alone is not evidence that its house geometry is faithful."}, {"title": "From pixels to production", "text": "The project includes PDF/mail-production tooling and a separate companion roadmap. The interesting integration problem is carrying the intended property identity and visual changes through each stage without treating every output as interchangeable."}], "learning": [{"title": "Separate geometry from appearance", "text": "A mesh can be geometrically constrained while a generated image changes materials or invents details. This project offers a concrete way to discuss those differences rather than equating photorealism with accuracy."}, {"title": "Coordinates are part of the product", "text": "Footprint winding, units, roof selection, camera orientation and scene extent are not merely graphics internals; they determine whether the result resembles the input building."}], "screenshots": [{"src": "assets/stories/media/leads/synthetic-roofs.png", "caption": "Original roof-mesh builders executed on the same synthetic footprint; plotted for inspection.", "kind": "actual geometry output / synthetic inputs", "date": "2026-10-30"}]}, {"id": "zommie", "aspiration": "ZommieBiz explores a different way to demonstrate web design: instead of telling a business owner what a better site might look like, generate a concrete industry-specific preview. The original plan connected business discovery, assessment of an existing site, structured content generation, preview hosting and a follow-up workflow. As a learning project, it reaches across browser-facing design and background systems: Next.js applications, shared database models, scoring, worker queues, template composition, asynchronous events and unsubscribe handling. The interesting personal-site story is the machinery that turns structured information into a preview, not an unsupported claim that the commercial business launched or converted customers.", "usage": ["An operator discovers candidate businesses and inspects signals about their existing websites. The score prioritizes review; it is not an objective measure of a business's quality.", "A generation worker prepares structured content and chooses an industry template. A preview record supplies the business fields and template ID.", "The preview app looks up a slug, checks expiry and selects the appropriate React template for a restaurant, salon, contractor, dentist or retail business.", "A business owner would browse the preview and use its contact CTA. For this portfolio run, only the actual contractor renderer is mounted with synthetic data; submission and tracking are disabled, and no outreach is sent."], "technology": [{"title": "A weighted score that can be inspected", "text": "The TypeScript score engine combines mobile and desktop performance, viewport metadata, builder detection, older library signals and HTML complexity. It reverses performance scores so worse performance produces a larger remake score, and reserves a special score for a missing website. This is a practical example of separating raw observations from a deterministic prioritization rule, with visible weights instead of an unexplained AI judgment."}, {"title": "Templates as structured presentation code", "text": "The preview route resolves a vertical/template ID, parses stored generated content and passes a typed business object into React components. Shared sections cover hero, services, gallery, hours/location and contact. Vertical configuration controls palettes, display formats and fallback imagery; contractor and restaurant previews use different presentation structures. The local capture runs these actual components, while keeping the database loader and server actions out of the capture harness."}, {"title": "Background work and event boundaries", "text": "The repository contains discovery, scoring, generation and outreach workers plus Prisma models. Outreach work includes idempotency, suppression checks, delayed sequencing, webhook signature verification and an unsubscribe surface. The February verification report marks static requirements complete but explicitly lists real mail delivery, unsubscribe interaction and webhook delivery as human checks. Those distinctions matter: code presence is not evidence of a fully exercised external service."}], "learning": [{"title": "Design a system that can explain its own decisions", "text": "A ranking score becomes easier to debug when inputs and weights are explicit. The same principle applies to stored content and template selection. This project supports a learning narrative about deterministic rules around generative systems, rather than treating generation as an opaque end-to-end solution."}, {"title": "A convincing preview needs truthful placeholder behavior", "text": "The recorded design context calls for example testimonials to be labeled, missing information to appear as placeholders and generated previews to remain noindexed. The actual capture still contains a stock-photo placeholder, which is a useful sign of the preserved state. It should not be replaced with invented client proof or presented as a finished customer site."}, {"title": "External workflows add responsibilities beyond rendering", "text": "Queues, retries, idempotency, suppression and signed webhook events are learning topics visible in this source. Rendering a nice preview is one subsystem; sending messages and respecting state transitions is another. The portfolio run deliberately exercises only the safe local presentation slice and does not turn a demo into actual outreach."}], "screenshots": [{"src": "assets/stories/media/zommie/preview.png", "caption": "Actual contractor-template components in a local capture harness.", "kind": "actual components with synthetic data; isolated renderer harness", "date": "2026-10-30"}, {"src": "assets/stories/media/zommie/services.png", "caption": "Original services and service-area sections rendering synthetic values.", "kind": "actual components with synthetic data; isolated renderer harness", "date": "2026-10-30"}]}, {"id": "defuzz", "aspiration": "Airbnb Defuzz explores uncertain record matching through a small browser extension and a local Python service. The project goal was to take listing signals with approximate coordinates and produce ranked property candidates from public records. The learning thread is extracting imperfect browser data, combining weak signals and showing uncertainty to a person. That is more specific—and more honest—than calling it a tool that always discovers an exact identity.", "usage": ["Open a listing page and use the extension. Its content/background path extracts coordinates and optional details such as bedrooms, bathrooms, host-name signals and amenities.", "Send the extracted signals to the local resolve endpoint, where geographic lookup supplies candidate records. This pass replaces the real lookup with invented records.", "Inspect candidate cards, their confidence and missing-field hints. Confidence is an application heuristic, not independently measured identification accuracy.", "Use copy actions only when appropriate to the actual workflow. No real listing, owner contact information, geocoding request or property database was accessed in this demonstration."], "technology": [{"title": "Browser extraction across a service boundary", "text": "The extension has to distinguish unavailable coordinates from merely missing optional fields. The popup then carries that partial result through a local API call instead of treating every missing value as an unrecoverable failure."}, {"title": "Pure scoring logic", "text": "server/scorer.py keeps matching separate from database and network I/O. That made it possible to execute the real scoring function on synthetic records and reuse its output in the actual popup UI."}, {"title": "Confidence and ambiguity", "text": "Bedroom, bathroom, name and pool signals contribute different evidence. Cluster detection and hints acknowledge that multiple candidates can remain plausible, especially when the location is approximate."}, {"title": "A testable popup", "text": "The capture uses the original popup markup and JavaScript. A fixture substitutes the Chrome messaging API and local resolve response; the scored records themselves come from executing the real Python scorer."}], "learning": [{"title": "Represent uncertainty explicitly", "text": "This project provides a way to discuss ranking, missing evidence, name ambiguity and the difference between a high heuristic score and a verified match."}, {"title": "Keep the core independently runnable", "text": "Separating a pure scorer from the Flask/database path makes the behavior easier to inspect and reproduce. Browser UI problems and scoring problems can then be investigated separately."}], "screenshots": [{"src": "assets/stories/media/defuzz/popup.png", "caption": "Actual popup code, mocked Chrome API and real scorer output from fictional records.", "kind": "local extension UI / synthetic fixture", "date": "2026-10-30"}]}, {"id": "navier", "aspiration": "This is a numerical notebook turned into a small Python laboratory. The aspiration was to explore model equations and fluid/gravity connections through code, starting with cases whose behavior can be checked. The planning documents are ambitious, but the portfolio framing is deliberately practical: implement solvers, compare to known answers, plot diagnostics and report limitations. Learning the numerical techniques is the story; this is not a claim to have solved Navier–Stokes regularity or established a new physics result.", "usage": ["Choose an experiment stream: simplified singularity models, large-dimensional effective equations or fluid-to-geometry diagnostics.", "Set an initial condition and numerical resolution, run the solver and inspect a plot or diagnostic rather than relying on a final scalar alone.", "Where an exact solution exists, compare against it. The reproduced experiment runs the actual CLM integrator on a sine initial condition and plots it beside the exact formula.", "Vary resolution or parameters and look for numerical artifacts before interpreting a sharp feature as physical behavior. This pass demonstrates one comparison, not the entire research program."], "technology": [{"title": "Spectral methods", "text": "The source uses periodic grids and Fourier-based operations. Spectral differentiation and Hilbert transforms provide compact implementations, but resolution and aliasing remain part of the experiment."}, {"title": "Adaptive stepping around strong signals", "text": "The CLM integrator scales its time step with the amplitude and advances with RK4. A known exact solution makes it possible to check the implementation rather than interpreting every output as a discovery."}, {"title": "Multiple experiment streams", "text": "The repository separates model equations, large-D systems and BKLS diagnostics. That modularity is useful because a success in a simplified model is not automatically a statement about the full fluid equations."}, {"title": "Reproducible plots", "text": "The included PNG was generated from the original committed solver at 512 periodic samples and specified times. It is a new local result of that fixture, not a historical experimental figure or a peer-reviewed finding."}], "learning": [{"title": "Numerics need a reference", "text": "Exact-solution comparisons give a practical route into error, resolution and time-stepping questions. A convincing plot is a starting point for checking a computation, not a substitute for those checks."}, {"title": "Separate ambition from result", "text": "The original idea connects difficult research areas. The implemented and reproducible learning outcome is a collection of experiments and diagnostics; originality and scientific conclusions need substantially more validation."}], "screenshots": [{"src": "assets/stories/media/navier/clm-comparison.png", "caption": "Actual CLM solver versus its exact solution for a synthetic sine initial condition.", "kind": "reproduced scientific plot", "date": "2026-10-30"}]}, {"id": "desktop", "aspiration": "Build a desktop bridge between physical training sensors and useful experiments: manage several BLE devices, collect sessions, annotate/extract shots and display predictions. The code makes Bluetooth, asynchronous GUI programming, data preparation and model integration source-supported exploration topics; personal learning outcomes and model accuracy remain undocumented.", "usage": ["The intended desktop entry point opens the SPAITR Analytics Dashboard, with per-device slots and a Discover Devices control.", "Discovery displays available BLE devices; selecting a device associates a BluetoothDevice and a session widget.", "The collection flow receives accelerometer/gyroscope/magnetometer streams and associates them with session work. A heartbeat detects a stream that has stopped and requests save/reset.", "Model artifacts are loaded for angle and speed prediction. Collection, annotation/extraction and analysis are related stages, but no prediction quality or live sensor run was verified here."], "technology": [{"title": "PyQt6 with asyncio", "text": "PyQt6 widgets form the multi-device dashboard and discovery dialog; qasync integrates async actions into the GUI."}, {"title": "Bluetooth device lifecycle", "text": "Bleak supplies the client/discovery integration. BluetoothDevice tracks last-data time and handles stream liveness, connection and disconnection."}, {"title": "Data and model tooling", "text": "NumPy/pandas and scikit-learn dependencies accompany shot extraction and joblib model loading. Loading a pre-trained artifact is visible in main_window.py, but provenance and accuracy were not established."}], "learning": [{"title": "Async work inside a GUI", "text": "Source-supported topic: keeping device discovery and connection lifecycle separate from widgets while handling multiple sessions."}, {"title": "Make collection usable", "text": "Commit evidence supports solo collection, save/reset fixes and sound cues. These are practical tool-building changes around the experiment, not just a machine-learning headline."}, {"title": "Know the model boundary", "text": "The repository integrates angle/speed model files, but this research did not run untrusted pickle artifacts, inspect training records or establish evaluation results. The portfolio should discuss the pipeline without inventing accuracy."}], "screenshots": [{"src": "assets/stories/media/desktop/heartbeat-source.png", "caption": "Actual stream-liveness source excerpt rendered for reading.", "kind": "source excerpt render", "date": "2026-10-30"}, {"src": "assets/stories/media/desktop/discovery-source.png", "caption": "Actual discovery-dialog loading-state source excerpt.", "kind": "source excerpt render", "date": "2026-10-30"}]}, {"id": "neuro", "aspiration": "Experiment with measuring movement and keeping it: Arduino/MPU6050 acquisition, low-latency SD logging, buttons, Bluetooth transmission and plotting. The repository's named experiments and acquisition code support these technical interests. No project statement establishes a neuroscience product or a personal learning narrative, so the name NeuroCode should not be expanded into one.", "usage": ["A developer selects the relevant Arduino experiment rather than launching a single finished app: raw MPU6050 reads, Bluetooth transmission, button testing or the SPAITR logger.", "The logger's acquisition function timestamps the sample with micros() and reads accelerometer and gyroscope axes through getMotion6.", "The logging sketch writes buffered binary data to an SD card and contains conversion/export support. UserFunctions emits a CSV header for micros, ax/ay/az and gx/gy/gz.", "Actual collection requires the matching board, wiring, sensor, SD hardware and libraries. No device was attached or data collection performed here; archived participant data was excluded."], "technology": [{"title": "Arduino/C++ sensor experiments", "text": "MPU6050_raw, baseGyroCode, buttonTesting and Bluetooth_transmition_test are separate sketches. The SPAITR-specific acquisition function reads six axes and prints timestamped records."}, {"title": "Buffered SD recording", "text": "The low-latency logger uses SdFat, block/buffer configuration and binary-to-CSV flow. Its header explicitly describes example logger behavior; those inherited example performance figures are not Joey's measured results."}, {"title": "Existing libraries and examples", "text": "I2Cdev/MPU6050 and generic logger scaffolding are third-party/example components. The story should distinguish adaptation/configuration and sensor wiring from creating those libraries."}], "learning": [{"title": "Go from a sensor register to a record", "text": "Source-supported topic: sampling raw acceleration/gyro axes, choosing ranges and keeping timestamps alongside the values."}, {"title": "Handle storage latency", "text": "Buffered logger code exposes timing, overrun and SD-write constraints. It is a useful early experiment story without claiming the example's published maximum rates as achieved performance."}, {"title": "Adapt rather than erase provenance", "text": "Mixed example/library code makes this a learning/adaptation archive entry. Joey-authored commits and user-confirmed jan1024 commits support contributions; inherited components remain separately attributed."}], "screenshots": [{"src": "assets/stories/media/neuro/acquisition-source.png", "caption": "Actual selected acquisition code rendered from NeuroCode/UserFunctions.cpp.", "kind": "source excerpt render", "date": "2026-10-30"}]}, {"id": "flipper", "aspiration": "A useful example of a learning exercise finding a second context. The Craigslist scraper explicitly started as an IT 630 assignment: collect online data and convert it to CSV. It later appears inside a team prototype named flipper with a Flutter frontend and Flask endpoints. The source supports learning how messy website markup becomes structured records, then exploring how those records might sit behind an application. It does not support calling flipper a completed resale platform, a working arbitrage engine or a launched business.", "usage": ["The scraper's original terminal workflow lets a user narrow a Craigslist location/category/search, parse listing pages and write listing records to CSV.", "getPostings extracts a title, timestamp and URL from the historical result-row markup.", "The portfolio fixture feeds that original parser two synthetic historical-style listings; it makes no live Craigslist requests.", "The Flask project contains product-related route placeholders, while the Flutter frontend is team work. Those surfaces were not validated as an integrated application."], "technology": [{"title": "DOM parsing and data cleanup", "text": "BeautifulSoup locates result rows, reads time attributes and listing links, and removes commas from titles before CSV output. The implementation shows the practical mechanics of extracting structured rows from a website."}, {"title": "Request and paging logic", "text": "urllib builds location/search URLs, and the script includes paged fetching with delays. These reflect the historical site structure and were not treated as a current, robust scraping API during the review."}, {"title": "A prototype across languages", "text": "The repository combines Python parsing and Flask with a Flutter client. The getProducts/getFlipper handlers still return empty jsonify placeholders; having the folders does not establish a complete data flow."}], "learning": [{"title": "Turning unstructured input into something reusable", "text": "The concrete learning area is the boundary from HTML to records: selecting useful fields, normalizing strings, handling page ranges and deciding what a CSV row should contain. The offline parser run proves that small boundary against a controlled fixture."}, {"title": "Reusing a technique without overstating the result", "text": "The coursework header and later scraper commit provide a real progression from assignment to prototype component. They also identify what Joey actually contributed, keeping the team frontend and incomplete backend integration separate."}], "screenshots": [{"src": "assets/stories/media/flipper/evidence.png", "caption": "Actual getPostings parser output from two synthetic historical-style listing rows.", "kind": "original parser / synthetic HTML fixture", "date": "2026-10-30"}]}, {"id": "ballot", "aspiration": "Ballot Buss is a hackathon team project around coordinating rides, with an Android client and Python planning/database pieces. For a learning-focused portfolio, the interesting part is the compressed collaboration: how a mobile interface, a record model and assignment logic meet at a shared contract. Joey's commits support database work, read tests, a homescreen and an icon. The wider routing algorithm belongs to the team context and is not attributed to Joey simply because his account contains a fork.", "usage": ["The intended workflow captures drivers and passengers, records capacities and locations, then generates assignments that the client can display.", "The planner models driver capacity and passenger groups; a plan scores remaining unassigned passengers.", "The Android client was inspected through source structure but was not rebuilt or connected to historical services."], "technology": [{"title": "A shared data model", "text": "Driver and Passenger classes make capacity, coordinates and groups explicit. Plan keeps a copy of routes and a score based on unassigned passengers. This is a concrete example of application state needing to be meaningful across components."}, {"title": "Assignment with constraints", "text": "The planner orders passengers by distance and explores assignments subject to available capacity. The local fixture uses the original generate_plan path and obtains a complete plan for a small synthetic case. That is not a city-scale routing benchmark."}, {"title": "Android meets Python", "text": "The repository includes Java Android activities and networking types alongside a Python server/planner. Joey's database and interface commits are specific evidence of contribution to those integration boundaries."}], "learning": [{"title": "Team integration under a short deadline", "text": "The source and commit sequence support learning about defining records, checking reads, and making a homescreen connect to the rest of a prototype. This is not a claim about the project's competition result or deployment impact."}, {"title": "Keeping attribution useful", "text": "A fork can still contain meaningful work. Naming the concrete commits—database rewrite/tests, homescreen and icon—communicates more than either claiming the entire system or excluding a collaborative project entirely."}], "screenshots": [{"src": "assets/stories/media/ballot/evidence.png", "caption": "Team planner source and actual output for a synthetic capacity/coordinate scenario.", "kind": "team algorithm fixture", "date": "2026-10-30"}]}, {"id": "maps", "aspiration": "Google Maps Business Copier is a small utility-sized experiment: take a business listing that is already open in a browser and remove the repetitive work of copying its name, address, phone number and website. It belongs in the portfolio as an exploration of browser automation and extension architecture, not as a large commercial platform. The source supports that narrow workflow directly.", "usage": ["Open a Maps place panel in a browser that supports the extension's Manifest V2/browser API setup.", "Open the extension popup. It checks whether the active tab is a Maps URL before asking the content script to extract fields.", "Read or copy individual fields. Copy All assembles address, company and website into one quoted CSV row, escaping internal quotation marks.", "The local walkthrough uses the original extraction and popup scripts with synthetic Maps-like DOM elements and a mocked browser message bridge. It does not install the extension against a real listing or collect any real business data."], "technology": [{"title": "A content script and a popup with separate jobs", "text": "content.js reads DOM elements in the listing page. popup.js controls the user interface and asks the active tab for data through browser.tabs.sendMessage. The manifest declares where that content script may run. This simple separation is the central extension concept: the popup's document does not itself contain the business page, so a message boundary is needed to access the right context."}, {"title": "DOM extraction is practical and fragile", "text": "The source looks for a known place-title class, data-item-id attributes for address and phone controls, and a website authority link. It also has fallback text and aria-label parsing. Those choices expose a useful learning topic: selectors make a focused tool possible quickly, but changes to a third-party interface can break them. The existing code is not evidence of an official Maps API integration or durable scraping coverage."}, {"title": "Clipboard output with useful edge cases", "text": "The popup fills read-only fields, provides per-field copy buttons and creates a CSV row from a selected subset. Its escaping doubles embedded quote characters before surrounding each value with quotes. The local fixture run verifies actual returned values and the copied CSV string. The manifest is version 2 and the source uses the browser namespace, so present-day browser compatibility is not established by the source alone."}], "learning": [{"title": "Small projects can isolate one new platform concept", "text": "This is worth including even without a sophisticated UI: it isolates extension permissions, active-tab inspection, message passing and content-script access. A useful writeup can explain those mechanics in a few concrete steps rather than inflating the project into a complete data platform."}, {"title": "Testing with fixtures separates behavior from live access", "text": "The local capture first executes the original content script on a synthetic DOM, then passes that result to the original popup through a mocked browser bridge. That proves a bounded behavior and permits a real screenshot of the shipped popup files without collecting real records. It is still a harness, not a live installed-extension test; that distinction belongs in the caption."}, {"title": "A finished tiny script can still have an unknown project state", "text": "The code may be small enough to understand completely, while its provenance, browser compatibility and last actual use remain unclear. Keep those unknowns visible. The learning story does not require pretending that it shipped widely or that it was intentionally abandoned on the filesystem timestamp date."}], "screenshots": [{"src": "assets/stories/media/maps/popup.png", "caption": "Original popup and original extraction code exercised using a synthetic Maps-like DOM and mocked extension message bridge.", "kind": "actual extension UI in a synthetic browser-API harness", "date": "2026-10-30"}]}, {"id": "learning", "aspiration": "A deliberately basic electronics learning exercise: connect a physical input to a physical output and make the state visible through serial output. Small examples deserve a place in the archive because they show the initial layer of a technique. Here the source supports learning Arduino-style setup/loop execution, pin configuration, digital reads/writes and the PlatformIO build workflow for an ESP32 development board. It does not establish a custom circuit design or a completed hardware product.", "usage": ["Build the project for the configured esp32doit-devkit-v1 target using PlatformIO.", "The code configures a button input on pin 22 and an LED output on pin 23, with serial output at 115200 baud.", "In loop, a LOW reading lights the LED and prints a pressed message; otherwise the LED is turned off.", "The new review compiles an isolated copy only. No board was connected, flashed or tested."], "technology": [{"title": "A hardware loop with visible feedback", "text": "setup initializes serial and configures the pins. loop reads the input and immediately writes an output state. Serial messages make the branch visible, useful when debugging the difference between software assumptions and wiring."}, {"title": "Board-specific build configuration", "text": "platformio.ini identifies Espressif 32, the DOIT ESP32 DEVKIT V1 board and Arduino framework. The isolated build reused installed PlatformIO tools and produced firmware.elf and firmware.bin without modifying the original project."}, {"title": "A useful warning in a small program", "text": "Compilation succeeds but warns that LED_BUILTIN is redefined. The source also comments about a pull-up while configuring INPUT, so the comment should not be mistaken for an enabled internal pull-up. Those are good concrete details for explaining this as an early exercise."}], "learning": [{"title": "Software meets electrical assumptions", "text": "The code assumes a LOW input means pressed, but verifying that requires the actual wiring and input bias. The build proves compile compatibility, not electrical behavior. Debounce, pull-ups and input stability are natural next topics; the existing code does not implement them."}, {"title": "Keeping a tiny exercise honest", "text": "The archive should name the small thing achieved rather than inflate it into an electronics system. A button-to-LED exercise is still evidence of learning the toolchain and digital I/O. Its original date and tutorial lineage remain unknown."}], "screenshots": [{"src": "assets/stories/media/learning/evidence.png", "caption": "Actual Arduino source and excerpt of successful isolated PlatformIO compile output.", "kind": "source / compiler output", "date": "2026-10-30"}]}, {"id": "gcal", "aspiration": "A compact API-integration learning exercise: start from a Calendar quickstart-style authorization/client setup, then inspect owned calendars and find a first event across them. The point is the technique rather than the scale. It introduces the chain from permission scopes and an API client to paginated-looking response objects, event timestamps and a small selection rule. The user confirmed that jan1024 was their college Git identity, so that commit name is attributed to Joey rather than incorrectly treated as an unrelated author.", "usage": ["The original script requests read-only Calendar access through a desktop OAuth flow and constructs a Calendar v3 client.", "It lists calendars, keeps calendars owned by the signed-in user, then requests the next event from each candidate calendar.", "A timestamp comparison selects an event and prints its summary/start information."], "technology": [{"title": "OAuth scope and client initialization", "text": "The script uses Google's API client and installed-app OAuth helper with calendar.readonly. That is the scaffolding of a standard API quickstart; it is explicitly presented as such rather than an original authentication system."}, {"title": "Filtering and aggregation", "text": "The custom workflow filters calendars by owner role, gets one next event for each and compares parsed start times. Python dictionaries, list comprehension and datetime handling perform the selection."}, {"title": "Time is part of correctness", "text": "Source compares current UTC time, timezone-normalized start values and a local-noon cutoff. All-day events and no-matching-event conditions need more careful handling than the preserved script provides. The historical commit claim is therefore not copied into a stronger product claim."}], "learning": [{"title": "From a quickstart to a task", "text": "The source supports learning how to move beyond a sample API call: combine calendar metadata and event data into a useful selection."}, {"title": "Finishing the edge cases", "text": "The preserved code is an exploration, not a resilient calendar assistant. It can leave first_event as a sentinel and assumes a usable timed event after an all-day-event branch. Those boundaries explain the last state without erasing the useful API learning."}], "screenshots": [{"src": "assets/stories/media/gcal/evidence.png", "caption": "Original event-selection body executed with fake Calendar API responses and a fixed clock.", "kind": "isolated post-authentication fixture", "date": "2026-10-30"}]}, {"id": "cs770", "aspiration": "A semester-scale collection for learning computer graphics from lower-level pieces. The repository is coursework, and that is a strength of the entry when stated plainly: it exposes the mathematics and mechanics that can disappear behind a scene editor. Source includes camera transforms and simple shader wrappers; commit history progresses through clipping, mesh generation, articulated robot parts, sphere intersections and ray-tracing-related changes. The user confirmed jan1024 is their college Git identity. Bundled teaching code and libraries still need to be separated from personal changes before attributing every file.", "usage": ["Choose an assignment directory and its matching build configuration rather than treating the repository as one application.", "Graphics exercises use C++ with OpenGL helpers and camera/model transform code; later history records ray and intersection work."], "technology": [{"title": "Transforms made explicit", "text": "The camera.cpp establishes eye/reference/up vectors, clip bounds and viewport-to-world conversion. The flat shader multiplies projection-view, model transform and vertex position, making the coordinate pipeline visible."}, {"title": "Shader programs and uniforms", "text": "flat_lighter.cpp contains vertex and fragment shader source plus uniform lookup/update calls. Despite the class name, its header explicitly says no lighting is performed; it passes a chosen vertex color through as a flat result."}, {"title": "Beyond a single template", "text": "The commit sequence records work on clipped meshes, cylindrical components and robot joints, then rays, spheres and mirror direction. These are evidence-backed learning topics, not a claim that every bundled framework component was original."}, {"title": "Student-marked ray-caster implementation region", "text": "asn07/rt.cpp explicitly marks functions students must implement. The region computes an inverse look-at camera transform, converts pixel centres into view-space rays and uses first-hit selection for object colors. This is a stronger pointer to assigned implementation work than attributing every framework helper to the student."}], "learning": [{"title": "Geometry, numerical tolerances and visual debugging", "text": "The history records both progress and limits: an early fast-motion segfault note, later projection fixes, and an epsilon adjustment near a ray-tracing submission. That supports a story about debugging geometry and numerical assumptions rather than only showing a final image."}, {"title": "Course frameworks versus authored work", "text": "This entry keeps the provided framework, GLM/GLFW dependencies and student edits distinct."}, {"title": "Testing a geometric edge case", "text": "The new C++ fixture executes the original sphere-intersection method on centre, offset and exactly tangent rays. The tangent is excluded because the code checks a strictly positive discriminant. That makes the boundary observable without inventing a rendered application screenshot."}], "screenshots": [{"src": "assets/stories/media/cs770/intersection-evidence.png", "caption": "Original C++ sphere-intersection routine compiled with a minimal test-only vector adapter and run against synthetic rays.", "kind": "original C++ routine / isolated fixture", "date": "2026-10-30"}, {"src": "assets/stories/media/cs770/evidence.png", "caption": "Source artifact only: no original graphics application was reproduced.", "kind": "source artifact / reproduction limitation", "date": "2026-10-30"}]}, {"id": "amazon", "aspiration": "AmazonBusinessCompare is shared tooling for monitoring product prices and presenting opportunities in a live dashboard. My contribution story is about the engineering underneath that interface: consistent deal eligibility, price-state handling and dashboard behavior. The aspiration recorded in project planning is a useful price-comparison workflow; the learning angle is how API ingestion, time-series state, business rules and a live UI stay consistent. The portfolio does not claim resale profit or business results.", "usage": ["Seed or track products through the documented extension/dashboard workflow, then let configured ingestion collect price snapshots. No real accounts or ingestion workers were started in this pass.", "Compare consumer and business prices, including quantity tiers, against per-product eligibility rules. The isolated run calls the shared threshold function with invented prices.", "Inspect active deal state and supporting history in the dashboard. My history includes changes to live state cells and processing behavior, rather than ownership of every dashboard component.", "Keep notification and scheduler decisions aligned with the same eligibility predicate. The local demonstration sends no alerts and makes no purchases."], "technology": [{"title": "A canonical eligibility predicate", "text": "src/core/thresholds.py centralizes decisions used by several pipeline paths. A tracked product with no configured targets should not become alertable merely because one caller applies a different default."}, {"title": "Money and tier semantics", "text": "Decimal arithmetic avoids unnecessary floating-point treatment of money. Quantity-tier identity also matters: a minimum order quantity is not necessarily a field-slot number, a distinction the source documents explicitly."}, {"title": "Time-series state and processing", "text": "The dip detector and processor compare new observations with history, while activation/deactivation has to preserve the intended state. A retrospective baseline, a current price and an alert condition are related but different concepts."}, {"title": "Dashboard truth", "text": "Joey-authored commits include exposing live state in dashboard cells. The portfolio’s actual-output capture shows the shared threshold function, not a reconstructed dashboard with made-up real-world deals."}], "learning": [{"title": "One rule across many entry points", "text": "A central learning topic is keeping scheduler, ingestion and UI paths from disagreeing about the same product. Centralizing a predicate is useful only if every caller uses the same semantics."}, {"title": "History includes reversals", "text": "The latest local commit reverts a restrictions requeue change. That matters for a personal story: a commit describing a feature is not proof that the feature remains part of the final state."}], "screenshots": [{"src": "assets/stories/media/amazon/execution.png", "caption": "Actual shared eligibility-function output on invented prices, displayed in an evidence viewer.", "kind": "actual execution / synthetic inputs", "date": "2026-10-30"}]}, {"id": "lamp", "aspiration": "A personalized wedding gift combining photographic panels, a wooden top and base, light and engraving. This is one of my favorite builds. The aspiration was to make a physical object with personal meaning while learning across materials and techniques. Unlike the programming entries, its strongest evidence will be the actual object: how the panels read when lit, how the wood frames them and where the personalization belongs.", "usage": ["This is a physical build, not software to launch locally. Its use is the object’s actual purpose described above.", "Present actual whole-object and detail photographs when available; no generated illustration is a substitute for an evidence photo."], "technology": [{"title": "The photograph becomes part of an object", "text": "The confirmed build uses photographic lithophane panels. The story can explain how images, transmitted light and a surrounding structure work together without assuming a particular printer, panel material or panel-making process."}, {"title": "Wood as structure and framing", "text": "The wooden top and base give the illuminated panels a physical home. Actual detail photographs are needed before describing joinery, tolerances or the order of assembly."}, {"title": "Personalization", "text": "The engraving is confirmed. Its exact machine, tooling, settings and finishing sequence are not yet documented, so this story does not assume it was CNC-cut or laser-engraved."}], "learning": [{"title": "Design across materials", "text": "A useful learning thread is coordinating image, light and wood as one object rather than treating them as unrelated parts."}, {"title": "Make the purpose visible", "text": "A wedding gift has a specific recipient and context. The visual story can show the personalization without publishing private photographic details that the people involved would rather keep private."}], "screenshots": []}, {"id": "sign", "aspiration": "A layered wooden welcome sign for a wedding, using a National Park Service-inspired motif. The aspiration was a personal event object whose form and lettering belong together, with the build also serving as a way to explore tools and techniques. The interesting visual quality is physical layering: the design has depth, edges and shadows, rather than existing only as a flat graphic.", "usage": ["This is a physical build, not software to launch locally. Its use is the object’s actual purpose described above.", "Present actual whole-object and detail photographs when available; no generated illustration is a substitute for an evidence photo."], "technology": [{"title": "Layered construction", "text": "The layered wooden form is confirmed. It opens a useful discussion about separating a graphic into physical parts, but the number of layers, material thicknesses and attachment method still need actual build records."}, {"title": "Lettering in a material", "text": "Personalized signage has to work at viewing distance and as a close-up object. The story can show placement and edge quality once photographed without inventing the cutting method."}, {"title": "A referenced visual language", "text": "The National Park Service motif is a design reference, not evidence of affiliation or an original invention of that visual language."}], "learning": [{"title": "Think in depth", "text": "The learning topic is translating a graphic idea into a layered object whose shadows and material edges contribute to the result."}, {"title": "Design for a setting", "text": "A welcome sign is used by arriving guests. Its role in the event helps explain decisions about hierarchy and legibility without assuming dimensions or fabrication details."}], "screenshots": []}, {"id": "mirror", "aspiration": "A mirror framed or structured with geometric wooden elements. The aspiration is a useful object with a strong relationship between geometry, wood and reflection, while exploring hands-on techniques. The confirmed facts are intentionally modest: I made the geometric wooden mirror. A convincing build story should be led by the actual shape and details, not a guessed construction process.", "usage": ["This is a physical build, not software to launch locally. Its use is the object’s actual purpose described above.", "Present actual whole-object and detail photographs when available; no generated illustration is a substitute for an evidence photo."], "technology": [{"title": "Geometry becomes physical", "text": "The design combines wood with a mirror and a geometric composition."}, {"title": "Reflective surfaces change presentation", "text": "A mirror’s appearance depends on what it reflects as well as its frame."}], "learning": [{"title": "Connect a layout to an object", "text": "This entry offers a practical learning thread around planning geometry, handling materials and checking alignment, without claiming a specific technique was used."}, {"title": "Present functional work clearly", "text": "A useful portfolio lesson is showing the mirror as both an object and something used in a space, with enough detail to understand the construction that is actually visible."}], "screenshots": []}, {"id": "woodarchive", "aspiration": "This group collects several confirmed builds: cutting boards, custom cornhole boards, a giant stacking game and mountain-shaped table numbers. Their shared aspiration is practical making—objects that are handled, played with or used at a gathering—while learning new tools and techniques. They should eventually become individual visual entries. For now, grouping them preserves the breadth without pretending the missing photos and specifications have been recovered.", "usage": ["This is a physical build, not software to launch locally. Its use is the object’s actual purpose described above.", "Present actual whole-object and detail photographs when available; no generated illustration is a substitute for an evidence photo."], "technology": [{"title": "Functional woodworking", "text": "Cutting boards belong to a different use case from signage or games. The fact of the build is confirmed; the wood species, glue-up, dimensions and finish are not."}, {"title": "Making for play", "text": "Cornhole boards and a giant stacking game connect fabrication to repeated physical use. The story can show how the actual objects are used without inventing regulation dimensions, construction standards or durability test results."}, {"title": "Small repeated objects", "text": "Mountain-shaped table numbers link shape, identification and event use. Their pattern, quantity, cutting process and numbering method need actual images or build notes before they are described."}], "learning": [{"title": "Use changes the design problem", "text": "Food contact, play and event identification create different practical questions. This is a way to discuss varied making interests without claiming every project used the same process."}, {"title": "Keep small projects in the archive", "text": "A useful object does not need a commercial launch to belong in a portfolio. These builds show the range of hands-on work alongside the larger software stories."}], "screenshots": []}, {"id": "fabrication", "aspiration": "This entry preserves the wider fabrication work already confirmed: CNC/engraving projects, workshop furniture and storage, and vehicle interiors. The common aspiration is learning tools and techniques by solving physical problems, including building the spaces and systems that support other work. The categories are confirmed, but individual project boundaries have not yet been documented well enough for a specific manufacturing story.", "usage": ["This is a physical build, not software to launch locally. Its use is the object’s actual purpose described above.", "Present actual whole-object and detail photographs when available; no generated illustration is a substitute for an evidence photo."], "technology": [{"title": "Digital fabrication", "text": "CNC and engraving connect digital preparation to a physical result. No machine, controller, cutter, material or CAM strategy is named without actual evidence."}, {"title": "Making the workshop useful", "text": "Furniture and storage are part of the workshop’s working infrastructure. Photos and dimensions are needed before describing a specific bench, cabinet, mount or organizational system."}, {"title": "Working in an existing space", "text": "Vehicle interiors involve a real surrounding structure, but the vehicle, component types and any electrical or structural work are not specified here. Those details should be documented project by project."}], "learning": [{"title": "Connect digital and physical workflows", "text": "These categories are a natural place to discuss the move from a design file or layout into an object. They do not establish that every wooden build was made on a CNC machine."}, {"title": "A workshop can be a project", "text": "Storage and furniture can reveal the practical side of making: creating an environment in which future projects are easier to do. This motivation fits the portfolio without inventing a completed shop system."}], "screenshots": []}];
